package com.bank.core;

import java.math.BigDecimal;

public class Account {
    // Declaration: instance variables — one independent copy per object.
    private final String accountId;       // set in constructor, never changes
    private String holderName;             // defaults to null until set
    private BigDecimal balance;            // defaults to null until set
    private int txnCount;                  // primitive → defaults to 0
    private boolean active;                // primitive → defaults to false

    // Instance initializer block: runs for EVERY object, after super(), before constructor body.
    {
        this.active = true;   // every freshly opened account starts active
        this.txnCount = 0;    // explicit, though int already defaults to 0
    }

    // Constructor initialization: 'this.' disambiguates field from parameter (shadowing).
    public Account(String accountId, String holderName, BigDecimal balance) {
        this.accountId = accountId;
        this.holderName = holderName;   // correct: field = parameter
        this.balance = balance;
    }

    // Behavior methods access instance variables directly (full object scope).
    public void debit(BigDecimal amount) {
        this.balance = this.balance.subtract(amount);
        this.txnCount++;
    }

    public void credit(BigDecimal amount) {
        this.balance = this.balance.add(amount);
        this.txnCount++;
    }

    // Correct setter: 'this.' avoids shadowing (holderName = holderName would be a no-op).
    public void setHolderName(String holderName) { this.holderName = holderName; }

    public String getAccountId() { return accountId; }
    public String getHolderName() { return holderName; }
    public BigDecimal getBalance() { return balance; }
    public int getTxnCount() { return txnCount; }
    public boolean isActive() { return active; }
}
