package com.bank.core;

import java.math.BigDecimal;
import java.util.logging.*;

public class InstanceVariableDemo {
    private static final Logger log = Logger.getLogger("BankLog");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Per-object independence: each Account carries its own instance variables.
        Account rajesh = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000.00"));
        Account priya  = new Account("CUR3001", "Priya Sharma", new BigDecimal("250000.00"));

        // Mutating Rajesh does NOT affect Priya — separate copies.
        rajesh.debit(new BigDecimal("50000.00"));
        rajesh.credit(new BigDecimal("12000.00"));

        log.info(() -> "Rajesh balance=" + rajesh.getBalance()
                        + " txnCount=" + rajesh.getTxnCount()
                        + " active=" + rajesh.isActive());
        log.info(() -> "Priya  balance=" + priya.getBalance()
                        + " txnCount=" + priya.getTxnCount()
                        + " active=" + priya.isActive() + "  (unchanged)");

        // Default values: a field left unset is null / 0 / false, never a crash.
        Account blank = new Account("TMP0001", null, new BigDecimal("0.00"));
        log.info(() -> "Blank account: holderName=" + blank.getHolderName()
                        + " (null default) txnCount=" + blank.getTxnCount()
                        + " (0 default) active=" + blank.isActive() + " (set by init block)");

        // Shadowing fix: setter uses this. so the field actually changes.
        priya.setHolderName("Priya Sharma (updated)");
        log.info(() -> "Priya holderName after setter = " + priya.getHolderName());
    }
}
